-- SIAP APBD: repair credentials for the 30 accounts in SIAP_APBD_Akun_Baru_PRIVAT.xlsx.
-- IMPORTANT: This script intentionally updates EXISTING rows. INSERT OR IGNORE cannot repair a bad salt/hash on an existing username.
-- It contains no plaintext passwords. Back up the Production D1 database before execution.
-- Run against database siap-apbd-mahakamulu (the Pages Production binding named DB).
-- It updates account metadata/credentials only; opd_data and documents are not modified.


-- Verification: every supplied account should return OK. This displays no password or hash values.
SELECT username, CASE WHEN typeof(password_salt)='text' AND length(password_salt)=32 AND password_salt NOT GLOB '*[^0-9a-fA-F]*' AND typeof(password_hash)='text' AND length(password_hash)=64 AND password_hash NOT GLOB '*[^0-9a-fA-F]*' THEN 'OK' ELSE 'REPAIR_NEEDED' END AS credential_format FROM users WHERE username IN ('admin_8c88ed43', 'opd01_inspektorat_58d8', 'opd02_dinas_pariwisata_p_f99e', 'opd03_dinas_pupr_perumah_61d5', 'opd04_satpol_pp_7245', 'opd05_bpbd_9e6d', 'opd06_dinsos_pppa_0fb8', 'opd07_ketahanan_pangan_p_d217', 'opd08_dlh_c379', 'opd09_disdukcapil_0019', 'opd10_dpmpk_572c', 'opd11_dishub_c131', 'opd12_diskominfo_statist_218c', 'opd13_dpmptsp_cacd', 'opd14_setda_31f6', 'opd15_setwan_8b81', 'opd16_bappedalitbang_ec1b', 'opd17_bapenda_9fe2', 'opd18_bkpsdm_f88f', 'opd19_bppd_81f6', 'opd20_kecamatan_long_apa_9140', 'opd21_kecamatan_long_pah_d4c1', 'opd22_kecamatan_long_bag_7d47', 'opd23_kecamatan_laham_70ee', 'opd24_kecamatan_long_hub_6942', 'opd25_bakesbangpol_8a90', 'opd26_puskesmas_long_bag_c5e6', 'opd27_dinkes_ppkb_1eb5', 'opd28_bpkad_571e', 'bpkad_verif_3124a0') ORDER BY username;
